CREATE TABLE IF NOT EXISTS workspaces(id text PRIMARY KEY,name text NOT NULL,allowed jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(workspace_id text REFERENCES workspaces(id),user_id text REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','editor','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(digest text PRIMARY KEY,user_id text REFERENCES users(id),workspace_id text REFERENCES workspaces(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),name text NOT NULL,contact text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,name),UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS sources(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),storage_key text UNIQUE NOT NULL,filename text NOT NULL,sha256 text NOT NULL,bytes integer NOT NULL,created_by text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS imports(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),supplier_id text NOT NULL,source_id text NOT NULL,created_by text NOT NULL REFERENCES users(id),status text NOT NULL CHECK(status IN ('parsing','mapping','preparing','review','committing','completed','failed')),revision integer NOT NULL DEFAULT 0,headers jsonb NOT NULL DEFAULT '[]',metadata jsonb NOT NULL DEFAULT '{}',row_count integer,preview jsonb,suggestion jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,supplier_id) REFERENCES suppliers(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id));
CREATE INDEX IF NOT EXISTS imports_activity ON imports(workspace_id,updated_at DESC,id);
CREATE TABLE IF NOT EXISTS revisions(import_id text REFERENCES imports(id),number integer NOT NULL,config jsonb NOT NULL,exclusions jsonb NOT NULL,created_by text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(import_id,number));
CREATE TABLE IF NOT EXISTS source_rows(import_id text REFERENCES imports(id),ordinal integer NOT NULL,values jsonb NOT NULL,PRIMARY KEY(import_id,ordinal));
CREATE TABLE IF NOT EXISTS products(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),supplier_id text NOT NULL,sku text NOT NULL,original_sku text NOT NULL,name text NOT NULL,description text,category text NOT NULL,price numeric(18,2) NOT NULL CHECK(price>=0),currency text NOT NULL,unit text NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,supplier_id,sku),FOREIGN KEY(workspace_id,supplier_id) REFERENCES suppliers(workspace_id,id));
CREATE INDEX IF NOT EXISTS products_workspace ON products(workspace_id,supplier_id);
CREATE TABLE IF NOT EXISTS commit_attempts(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),import_id text NOT NULL REFERENCES imports(id),revision integer NOT NULL,key text NOT NULL,actor_id text NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'pending',error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,key));
CREATE TABLE IF NOT EXISTS receipts(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),import_id text UNIQUE NOT NULL REFERENCES imports(id),revision integer NOT NULL,attempt_id text UNIQUE NOT NULL REFERENCES commit_attempts(id),actor_id text NOT NULL REFERENCES users(id),counts jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),product_id text REFERENCES products(id),import_id text REFERENCES imports(id),record integer,actor_id text REFERENCES users(id),kind text NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_product ON audit_events(workspace_id,product_id,created_at DESC);
CREATE TABLE IF NOT EXISTS saved_mappings(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),supplier_id text NOT NULL,version integer NOT NULL,headers jsonb NOT NULL,config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(supplier_id,version),FOREIGN KEY(workspace_id,supplier_id) REFERENCES suppliers(workspace_id,id));
CREATE TABLE IF NOT EXISTS jobs(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),import_id text NOT NULL REFERENCES imports(id),kind text NOT NULL CHECK(kind IN ('parse','prepare','commit','suggest')),revision integer NOT NULL,actor_id text NOT NULL REFERENCES users(id),payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','done','failed')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(status,available_at);
